const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define regions for northern and southern Ethiopia
  const northEthiopia = ee.Geometry.Polygon([
    [[37.5, 14.5], [42.0, 14.5], [42.0, 12.0], [37.5, 12.0], [37.5, 14.5]]
  ]);

  const southEthiopia = ee.Geometry.Polygon([
    [[35.0, 8.0], [42.0, 8.0], [42.0, 4.0], [35.0, 4.0], [35.0, 8.0]]
  ]);

  // Load CHIRPS precipitation data
  const chirps = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY');

  // Function to calculate total precipitation for a given period and region
  function calculatePrecipitation(startDate, endDate, region) {
    const collection = chirps
      .filterDate(startDate, endDate)
      .filterBounds(region);

    if (collection.size().getInfo() === 0) {
      return null;
    }

    const totalPrecip = collection.sum();

    // Calculate valid pixel count
    const count = totalPrecip.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: 5000,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

    if (count === 0) {
      return null;
    }

    const meanPrecip = totalPrecip.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: region,
      scale: 5000,
      maxPixels: 1e9
    }).get('precipitation').getInfo();

    return {mean: meanPrecip, count: count};
  }

  // Calculate 2021 precipitation (Oct-Nov)
  const precip2021North = calculatePrecipitation('2021-10-01', '2021-11-30', northEthiopia);
  const precip2021South = calculatePrecipitation('2021-10-01', '2021-11-30', southEthiopia);

  // Calculate long-term average (2000-2013, Oct-Nov)
  let longtermNorth = 0;
  let longtermSouth = 0;
  let validYears = 0;

  for (let year = 2000; year <= 2013; year++) {
    const period = `${year}-10-01`;
    const north = calculatePrecipitation(period, `${year}-11-30`, northEthiopia);
    const south = calculatePrecipitation(period, `${year}-11-30`, southEthiopia);

    if (north && south) {
      longtermNorth += north.mean;
      longtermSouth += south.mean;
      validYears++;
    }
  }

  // Check for data availability
  if (!precip2021North || !precip2021South || validYears === 0) {
    if (validYears === 0) {
      console.log("No valid long-term data found");
      console.log("<answer>C1</answer>");
    } else if (!precip2021North || !precip2021South) {
      console.log("2021 data missing for one or both regions");
      console.log("<answer>C1</answer>");
    }
    return;
  }

  // Calculate long-term averages
  longtermNorth /= validYears;
  longtermSouth /= validYears;

  // Calculate anomalies (2021 / long-term average)
  const anomalyNorth = precip2021North.mean / longtermNorth;
  const anomalySouth = precip2021South.mean / longtermSouth;

  // Validate results
  if (isNaN(anomalyNorth) || isNaN(anomalySouth) || 
      anomalyNorth <= 0 || anomalySouth <= 0 || 
      anomalyNorth > 10 || anomalySouth > 10) {
    console.log(`Invalid anomaly values: North=${anomalyNorth.toFixed(3)}, South=${anomalySouth.toFixed(3)}`);
    console.log("<answer>C3</answer>");
    return;
  }

  // Print stats
  console.log(`2021 North: ${precip2021North.mean.toFixed(1)}mm (${precip2021North.count} pixels)`);
  console.log(`2021 South: ${precip2021South.mean.toFixed(1)}mm (${precip2021South.count} pixels)`);
  console.log(`Long-term North: ${longtermNorth.toFixed(1)}mm`);
  console.log(`Long-term South: ${longtermSouth.toFixed(1)}mm`);
  console.log(`North Anomaly: ${anomalyNorth.toFixed(3)}`);
  console.log(`South Anomaly: ${anomalySouth.toFixed(3)}`);

  // Determine answer
  if (anomalySouth < anomalyNorth) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
